#include "ember/SfvLoadoutNotes.hxx"

#include "ember/SfvCatalog.hxx"

#include <optional>

namespace sfve::adapter {

namespace {

// One embedded catalog: its language tag and its .po text in parts (each an
// entry or so, ending with nullptr), which run together are the file: one
// literal of 180 entries would pass MSVC's limit. The table below ends with
// {nullptr, nullptr}.
struct EmbeddedCatalog {
	const char* tag;
	const char* const* parts;
};

// Generated by CMakeLists.txt from locales/loadout/*.po (sfve_ember): a
// kLoadout_<tag> array of parts for each language the library declares, and
// the LoadoutCatalogs table of them.
#include "SfvLoadoutCatalogs.inc"

} // namespace

std::string LoadoutNoteKey(std::string_view fighterCode, picks::LoadoutPart part, int choice)
{
	if (fighterCode.empty() || choice < 0 || choice >= picks::kPartChoices) return {};
	std::string key(fighterCode);
	key += part == picks::LoadoutPart::VSkill ? ".vs" : ".vt";
	key += (char)('1' + choice);
	return key;
}

// Stream D: the lookup (the active language's catalog, then English). Until
// then every note is empty.
std::string LoadoutNoteFor(std::string_view, picks::LoadoutPart, int)
{
	return {};
}

std::string LoadoutNote(int fighter, picks::LoadoutPart part, int choice)
{
	return LoadoutNoteFor(FighterCode(fighter), part, choice);
}

std::optional<std::string> LoadoutCatalogText(std::string_view tag)
{
	for (const EmbeddedCatalog* catalog = LoadoutCatalogs; catalog->tag; ++catalog) {
		if (tag != catalog->tag) continue;
		std::string text;
		for (const char* const* part = catalog->parts; *part; ++part) text += *part;
		return text;
	}
	return std::nullopt;
}

} // namespace sfve::adapter
